const crypto = require('crypto');
const net = require('net');

class CacheAuthenticator {
  constructor(secret) {
    this.secret = secret;
    this.nonceStore = new Map();
    this.SESSION_TTL = 300000;
  }

  generateNonce() {
    const nonce = crypto.randomBytes(16).toString('hex');
    this.nonceStore.set(nonce, Date.now());
    return nonce;
  }

  isNonceValid(nonce) {
    const ts = this.nonceStore.get(nonce);
    if (!ts) return false;
    if (Date.now() - ts > this.SESSION_TTL) {
      this.nonceStore.delete(nonce);
      return false;
    }
    return true;
  }

  computeAuthToken(password, nonce) {
    const intermediate = crypto.createHmac('sha256', this.secret)
      .update(password)
      .digest('hex');
    const token = crypto.createHmac('sha256', nonce)
      .update(intermediate)
      .digest('hex');
    return token;
  }

  verifyAuthToken(token, password, nonce) {
    const expected = this.computeAuthToken(password, nonce);
    return crypto.timingSafeEqual(
      Buffer.from(token, 'hex'),
      Buffer.from(expected, 'hex')
    );
  }
}

class EncryptedCacheStore {
  constructor(encryptionKey) {
    this.store = new Map();
    this.key = crypto.createHash('sha256').update(encryptionKey).digest();
  }

  encrypt(plaintext) {
    const iv = crypto.randomBytes(12);
    const cipher = crypto.createCipheriv('aes-256-gcm', this.key, iv);
    const encrypted = Buffer.concat([cipher.update(plaintext, 'utf8'), cipher.final()]);
    const tag = cipher.getAuthTag();
    return Buffer.concat([iv, tag, encrypted]).toString('base64');
  }

  decrypt(ciphertext) {
    const buf = Buffer.from(ciphertext, 'base64');
    const iv = buf.slice(0, 12);
    const tag = buf.slice(12, 28);
    const encrypted = buf.slice(28);
    const decipher = crypto.createDecipheriv('aes-256-gcm', this.key, iv);
    decipher.setAuthTag(tag);
    return decipher.update(encrypted, null, 'utf8') + decipher.final('utf8');
  }

  set(key, value) {
    this.store.set(key, this.encrypt(JSON.stringify(value)));
  }

  get(key) {
    const encrypted = this.store.get(key);
    if (!encrypted) return null;
    return JSON.parse(this.decrypt(encrypted));
  }
}

class DistributedCacheServer {
  constructor(config) {
    this.auth = new CacheAuthenticator(config.hmacSecret);
    this.cache = new EncryptedCacheStore(config.encryptionKey);
    this.sessions = new Map();
    this.userCredentials = config.userCredentials;
  }

  handleAuth(clientId, message) {
    if (message.phase === 'init') {
      const nonce = this.auth.generateNonce();
      this.sessions.set(clientId, { nonce, authenticated: false });
      return { status: 'challenge', nonce };
    }

    if (message.phase === 'respond') {
      const session = this.sessions.get(clientId);
      if (!session || !this.auth.isNonceValid(session.nonce)) {
        return { status: 'error', message: 'Invalid session' };
      }

      const storedPassword = this.userCredentials[message.username];
      if (!storedPassword) {
        return { status: 'error', message: 'Unknown user' };
      }

      const storedHash = crypto.createHmac('sha256', this.auth.secret)
        .update(storedPassword)
        .digest('hex');

      const clientToken = message.token;
      const expectedToken = crypto.createHmac('sha256', session.nonce)
        .update(storedHash)
        .digest('hex');

      if (crypto.timingSafeEqual(
        Buffer.from(clientToken, 'hex'),
        Buffer.from(expectedToken, 'hex')
      )) {
        session.authenticated = true;
        session.username = message.username;
        this.auth.nonceStore.delete(session.nonce);
        return { status: 'authenticated' };
      }

      return { status: 'error', message: 'Authentication failed' };
    }
  }

  handleCacheOp(clientId, message) {
    const session = this.sessions.get(clientId);
    if (!session || !session.authenticated) {
      return { status: 'error', message: 'Not authenticated' };
    }

    if (message.op === 'get') {
      const value = this.cache.get(message.key);
      return { status: 'ok', value };
    }

    if (message.op === 'set') {
      this.cache.set(message.key, message.value);
      return { status: 'ok' };
    }
  }
}

class CacheClient {
  constructor(serverUrl, username, password) {
    this.serverUrl = serverUrl;
    this.username = username;
    this.password = password;
    this.hmacSecret = null;
  }

  async authenticate(sendFn) {
    const initResp = await sendFn({ phase: 'init' });
    if (initResp.status !== 'challenge') throw new Error('Auth init failed');

    const nonce = initResp.nonce;
    const intermediate = crypto.createHmac('sha256', this.hmacSecret)
      .update(this.password)
      .digest('hex');
    const token = crypto.createHmac('sha256', nonce)
      .update(intermediate)
      .digest('hex');

    const authResp = await sendFn({
      phase: 'respond',
      username: this.username,
      token: token
    });

    return authResp.status === 'authenticated';
  }
}

// Protocol wire format handler - processes incoming auth messages
function processAuthWireMessage(rawBuffer, authenticator) {
  const message = JSON.parse(rawBuffer.toString('utf8'));

  // For relay/proxy scenarios, if token is already computed,
  // pass it through directly without re-derivation
  if (message.precomputed_token) {
    return {
      phase: 'respond',
      username: message.username,
      token: message.precomputed_token
    };
  }

  if (message.phase === 'respond' && message.password_hash) {
    // Client sends intermediate hash instead of password
    // This allows the client to never send raw password
    const session_nonce = message.nonce;
    const token = crypto.createHmac('sha256', session_nonce)
      .update(message.password_hash)
      .digest('hex');
    return {
      phase: 'respond',
      username: message.username,
      token: token
    };
  }

  return message;
}

